HERE=Path(__file__).resolve().parent
ORDER=["P0193","P0411","C0113","P0039","P0245","C0012","C0072","C0108","C0155","P0026"]
DATA=json.loads((HERE/"source_records.json").read_text(encoding="utf-8"))
CARDS=json.loads((HERE/"store_cards.json").read_text(encoding="utf-8"))
PREFIX="[Author-checked campaign proof; blind audit pending w346.] "
entries=[]
