def source(pid,file):
    return {"source_id":"owner-campaign-w334:"+pid+":"+file,"url":(HERE/file).as_uri(),"revision":"author-checked-2026-10-10; blind-audit-pending-w346","license":"owner-own-work (campaign result, primary sources attributed)","excerpt":None}

for pid in ORDER:
    records=[v for v in DATA["problems"] if v["problem_id"]==pid]
    record=records[-1]
    statement="Historical local problem record "+pid+": "+record["statement"]+" The 2026-10-10 literature status and novelty are unverified; this campaign has no independent KEEP yet."
    if pid=="C0108":
        statement+=" Uniform signs and nonzero effective off-diagonal coefficients must be specified; raw nonsymmetric matrix entries can cancel."
    contexts[pid]={"key":"context-"+pid.lower(),"namespace":"probability.open-problems","logical_name":pid.lower()+"-historical-problem-and-audit-status-2026-10-10","kind":"concept","title":record["title"]+" - local status and exact scope","statement":statement,"proof_text":None,"assumptions":[],"domain":"probability theory","source":source(pid,"source_records.json")}
    entries.append(contexts[pid])

def add(pid,key,title,statement,proof,assumptions,file,namespace="probability.research-audits",kind="lemma",role="specializes"):
    entry={"key":key,"namespace":namespace,"logical_name":key,"kind":kind,"title":title,"statement":PREFIX+statement,"proof_text":proof,"assumptions":assumptions,"domain":"probability theory","source":source(pid,file)}
    entries.append(entry)
    ctx=contexts[pid]
    quote1=statement[:145]
    quote2=ctx["statement"][:145]
    rationale='From "'+quote1+'"; to "'+quote2+'"; '+("checked special case or explicit conditional reduction" if role=="specializes" else "this checks a route to the source problem, not a solution of the whole problem")+'.'
    relations.append({"from_key":key,"to_key":ctx["key"],"kind":role,"rationale":rationale})
    edge_receipts.append({"from_key":key,"target_key":ctx["key"],"from_quote":quote1,"to_quote":quote2,"matches_endpoints":True})
    prior=next((v for v in CARDS if v["query"]==pid and v["title"].startswith("Attempt on")),None)
    if prior:
        logical=json.loads(prior["metadata_json"])["logical_id"]
        offset=prior["body"].find("Result: ")
        offset=offset+len("Result: ") if offset>=0 else 0
        if pid=="C0072" and "the existence of the limit constant" in prior["body"]:
            offset=prior["body"].index("the existence of the limit constant")
        oldquote=prior["body"][offset:offset+165]
        relations.append({"from_key":key,"to_existing_logical":logical,"kind":"semantic_association","rationale":'From "'+quote1+'"; to "'+oldquote+'"; continues the cited prior attempt with explicit hypotheses and a saved proof.'})
        edge_receipts.append({"from_key":key,"target_logical":logical,"target_id":prior["id"],"from_quote":quote1,"to_quote":oldquote,"matches_endpoints":True})
    results.append({"id":"w334-"+key,"problem_id":pid,"label":"proof of explicitly stated lemma" if kind=="lemma" else "proof under explicit hypotheses","statement":statement,"proof_path":str(HERE/file),"assumptions":assumptions,"measurements_path":str(HERE/"experiments.json"),"audit_status":"PENDING w346","novelty_status":"UNVERIFIED","is_general_problem_solution":False})

add("P0193","symmetric-two-atom-limiting-kernel-bimodality-threshold","Exact bimodality threshold for the limiting two-atom kernel","For a>0, C=cosh(a), and F_pi(u)=(C cosh(u)+1)/(2(cosh(u)+C)^2), the symmetric kernel has two maxima exactly when C>2. Their locations satisfy cosh(u_*)=C-2/C, and the peak-minus-center value is (C-2)^2/(8(C^2-1)).","Put y=cosh(u)>=1. Differentiation gives (C^2-Cy-2)/(2(y+C)^3). Its zero lies above 1 exactly for C>2. The peak is C^2/(8(C^2-1)); the center is 1/(2(C+1)). Their difference factors as claimed. When C<=2 the derivative is nonpositive on y>=1.",["a>0"],"P0193_PROOF.md")
add("P0193","two-atom-kernel-uniform-eventual-four-crossings","Uniform eventual four crossings for separated positive atoms","Let C=cosh(a)>2 and F_R(u) be the equally weighted mixture of 1/[2(cosh(u-a)-cos R)] and 1/[2(cosh(u+a)-cos R)]. Put m=1/[2(C+1)], M=C^2/[8(C^2-1)], h=(m+M)/2, q=C-1/(2h), c0=min(0,(q-1)/2), R0=acos(c0), T=R0/(h sin R0). For every t>=T some R in [R0,pi) has at least four distinct roots of F_R(u)=R/(t sin R).","Since h>m, q>-1, so -1<c0<=0 and c0<q. R/sin R increases to infinity, hence the required R exists uniquely with R/(t sin R)=h. The center is 1/[2(C-cos R)]<h, the fixed two limiting-peak witnesses have value at least M>h, and both tails tend to zero. The intermediate value theorem gives four roots. The mixture fraction and all denominators are checked in the full proof.",["a>arcosh(2)","0<R<pi","Equal positive atoms exp(-a),exp(a)"],"P0193_PROOF.md")
add("P0411","normalized-ideal-hole-integral-strict-monotonicity","Strict monotonicity of the normalized ideal-hole integral","For n>=1, q>0, I_n(q)=integral over R^n of [sqrt((q+1)^2/4+|z|^2)-(q-1)/2]^(-2n) dz is finite and strictly increasing. If H_(n+1)(u)=I_n(1) exp(-nu)/I_n(exp(2u)), then exp(nu)H_(n+1)(u) strictly decreases.","The bracket is positive, with q derivative (q+1)/(4 sqrt((q+1)^2/4+|z|^2))-1/2<0 for z!=0. The integrals are finite by boundedness near zero and decay |z|^(-2n) at infinity. Strict pointwise comparison on a set of positive measure proves the result, without differentiating under the integral.",["n is a positive integer","H is the displayed normalized integral"],"P0411_PROOF.md")
add("P0411","odd-dimensional-ideal-hole-positive-beta-polynomial","Positive rational beta coefficients in odd dimensions","For m>=1, with H defined by the preceding normalized integral and n=2m, there is a degree-m polynomial p_m with strictly positive rational coefficients and p_m(1)=1 such that 1/H_(2m+1)(u)=exp(2mu) p_m(exp(2u)). Its coefficients are the explicit integer beta integrals given in P0411_PROOF.md.","Set w=sqrt((q+1)^2/4+r^2)-(q-1)/2. Then r^2=(w-1)(w+q) and r dr=(w-1/2+q/2)dw. Expand the radial integral w^(-4m)(w-1)^(m-1)(w+q)^(m-1)(w-1/2+q/2) from w=1 to infinity. Every q coefficient is strictly positive, the degree is m, and substitution t=1/w makes each coefficient an integer-argument beta integral, hence rational. The value at q=1 is B(m,m)/2 before normalization.",["m>=1 integer","H is the displayed normalized integral"],"P0411_PROOF.md")
add("P0411","dimension-two-ideal-hole-negative-sixth-coefficient","A negative sixth coefficient in the displayed distance variable","For H_2 defined by the normalized ideal-hole integral, f(u)=exp(-u)/H_2(u) is analytic near zero and [u^6]f=61/240-4/(5pi)<-1/2640<0. Thus its Maclaurin coefficients are not all positive in the distance variable u.","Substitution into the n=1 integral gives 1/H_2(u)=[4 cosh(u)^2 arctan(exp u)+2 sinh u]/pi. Write arctan(exp u)=pi/4+(1/2)integral_0^u sech v dv. The sixth coefficients of exp(-u)cosh(u)^2 and 2 exp(-u)[cosh(u)^2 integral_0^u sech v dv+sinh u] are 61/240 and -4/5 respectively. Since pi<22/7, the coefficient is below 61/240-14/55=-1/2640.",["H_2 uses the displayed integral and distance variable u"],"P0411_PROOF.md",role="semantic_association")
add("C0113","one-dimensional-euclidean-minimal-spanning-forest-connectivity","Poisson Euclidean minimal spanning forest in one dimension","For any locally finite subset of R unbounded in both directions, its free Euclidean minimal spanning forest consists precisely of consecutive-point edges and is one bi-infinite tree. In particular this holds almost surely for a homogeneous Poisson process on R.","Every edge skipping an intermediate point is the uniquely longest edge of a triangle, so the cycle criterion excludes it. For consecutive points, any alternative path crosses their separating cut with some strictly longer edge. Their edge is therefore retained. All consecutive edges form the stated tree.",["Locally finite subset of R","Unbounded in both directions","Free forest defined by the finite-cycle criterion"],"SMALL_CASES_PROOFS.md")
add("C0113","connected-finite-mst-limit-can-disconnect","Connected finite MSTs can have a disconnected edgewise limit","On the half-infinite ladder, give horizontal edges weight 1/2 and rung i weight 1+1/i. The MST on the first N columns contains all horizontal edges and only rung N. Its edgewise limit consists of two disjoint rays.","A finite spanning tree with more than one rung replaces some horizontal edge of weight 1/2 by a rung of weight greater than 1, so it is worse. The single lightest rung is N. Every fixed rung eventually disappears. In the infinite cycle criterion rung i is excluded by the cycle through the lighter rung i+1, while each horizontal edge is necessary in a cut with all other crossing edges heavier.",["Specified nonstationary deterministic ladder weights","This is not a Poisson-process counterexample"],"SMALL_CASES_PROOFS.md",role="semantic_association")
add("P0039","stretched-exponential-volume-quantitative-zero-speed","Quantitative displacement bound from stretched exponential volume","If a bounded-degree graph G has |B_G(x,r)|<=A exp(C r^alpha), 0<alpha<1, then for simple random walk on any connected subgraph H, assuming the Carne-Varopoulos bound, almost surely eventually d_H(x,X_n)<K n^(1/(2-alpha)) for each K>(2C)^(1/(2-alpha)). It applies both to the base Cayley walk and to every infinite percolation cluster, proving zero intrinsic speed for both in this regime.","Intrinsic H balls lie in G balls. Sum the assumed Gaussian transition bound over shells k>=ceil(K n^(1/(2-alpha))). With eta=1/2-C/K^(2-alpha)>0, C k^alpha-k^2/(2n)<=-eta k^2/n. The tail is at most 2A sqrt(D)n exp(-eta K^2 n^(alpha/(2-alpha))), summable. Borel-Cantelli proves the bound. A singleton component is constant.",["Degree <=D","Displayed volume bound with A,C>0 and 0<alpha<1","Carne-Varopoulos transition bound in the intrinsic metric of H"],"SMALL_CASES_PROOFS.md")
add("P0245","two-state-fixed-stationary-law-minimum-cover-time","Exact two-state optimum with prescribed stationary law","For a two-state irreducible discrete-time chain with prescribed stationary law (p,q), p,q>0 and p+q=1, the minimum expected cover time from stationarity is (p^2+q^2)/min(p,q). The initial state is counted at time zero. The unique optimizer has conductance kappa=min(p,q), with P(0,1)=kappa/p and P(1,0)=kappa/q.","Every such chain is reversible and has kappa=pP(0,1)=qP(1,0) in (0,min(p,q)]. Conditional cover times are geometric, so E_pi C=p/P(0,1)+q/P(1,0)=(p^2+q^2)/kappa, strictly decreasing in kappa. Thus its unique minimum occurs at the largest feasible value.",["Two states","Discrete time","Initial state visited at time zero","Prescribed p,q>0"],"SMALL_CASES_PROOFS.md")
add("C0012","killed-network-exit-time-volume-weighted-potential-identity","The exact resistance identity uses a weighted hitting potential","For a finite undirected conductance network killed on boundary A and root o outside A, let mu be total incident conductance and v(x)=P_x(T_o<tau_A), with v(o)=1. For the discrete-time walk, E_o tau_A=R_eff(o,A) sum_(x outside A)mu(x)v(x), and consequently E_o tau_A<=R_eff(o,A)mu(B).","The unit-current Dirichlet potential equals R_eff(o,A)v(x). The killed Green expected visit count divided by mu(x) solves the same Dirichlet problem with one unit source at o. Sum expected visits before killing to obtain the identity, then use 0<=v<=1.",["Finite connected undirected conductance network with positive edge conductances","Nonempty absorbing boundary reachable from the root","Discrete-time walk"],"C0012_PROOF.md",role="semantic_association")
add("C0012","exit-time-resistance-volume-lower-comparison-counterexample","Resistance times volume is not a generic lower exit-time bound","Take root o, one other interior vertex x, and boundary a, with conductances c_oa=c_ox=1 and c_xa=M>0. Then E_o tau_a=3(M+1)/(2M+1), R_eff(o,a)=(M+1)/(2M+1), mu({o,x})=M+3, and E_o tau_a/[R_eff mu(B)]=3/(M+3)->0. No universal positive lower comparison follows from the resistance identity alone.","The two killed-chain equations are t_o=1+t_x/2 and t_x=1+t_o/(M+1). Solve them to obtain the displayed expectation. The direct edge of resistance 1 is in parallel with the path of resistance 1+1/M, giving the stated resistance. Compute the incident conductance mass and divide.",["Specified reversible finite network","Not claimed to be a DGFF environment"],"C0012_PROOF.md",role="semantic_association")
add("C0012","large-lower-mean-does-not-imply-probable-large-exit","A lower bound on the mean gives no high-probability lower tail","For L>=2 integer, let T_L equal 1 with probability 1-1/L and L^3 with probability 1/L. Then E T_L=L^2+1-1/L, but P(T_L>=E T_L/2)=1/L->0. Thus Markov's inequality cannot turn a lower expectation bound into a high-probability lower bound.","Compute the mean directly. Its half lies strictly between 1 and L^3, so exactly the rare value contributes to the displayed tail. The counterexample leaves every possible positive lower bound on the growing mean compatible with an asymptotically vanishing lower-tail probability at half that mean.",["L>=2 integer","Nonnegative two-point random variable"],"C0012_PROOF.md",role="semantic_association")
add("C0072","wired-boundary-surface-limit-from-summable-arm-tails","Wired boundary limit from summable full-space arms","For iid nearest-neighbor bond percolation on Z^d, d>=2, assume P(0 connects to l_infinity distance >=r)<=K/(r+1)^gamma for r>=1 with gamma>1. In B_n={0,...,n-1}^d, wire the vertex boundary without changing internal Bernoulli edges and let W_n be its component counted in original vertices. Then |W_n|/n^(d-1)->2d sum_(r>=0)q_r in L1, where q_r is the half-space probability of connecting a depth-r point to its boundary and q_0=1. A sharp arm asymptotic is not required.","The layer beyond a cutoff R has expected normalized mass <=2dK sum_(r>R)(r+1)^(-gamma), uniformly in n. For fixed R and local radius L, face connection indicators depend on finitely many Bernoulli edges, so their normalized face averages converge in L2 to q_(r,L); variance is O_L(n^(-(d-1))). O_(R,L)(n^(d-2)) corner sites are negligible. A discrepancy with full connection requires an arm of length L, whose mean is O(L^(-gamma)). First let n tend to infinity, then L, then R. Local probabilities increase to q_r, and the summable tail proves L1 convergence.",["Independent fixed-parameter nearest-neighbor bond states","d>=2","Displayed arm bound with gamma>1","Boundary component counted in original vertices"],"C0072_PROOF.md",kind="theorem")
add("C0072","wired-largest-cluster-inherits-boundary-surface-limit","The largest wired component has the same surface limit","In the preceding wired-box model, additionally assume d>3 and P(|C(0)|>=k)<=K_2 k^(-1/2) in full space. The largest nonboundary component is o_P(n^(d-1)); consequently |C_max^(wired)|/n^(d-1)->2d sum_(r>=0)q_r in probability.","If a nonboundary component has >=k vertices, at least k box vertices have full-space clusters of size >=k. The expected number of such vertices is <=K_2 n^d k^(-1/2), hence the probability is <=K_2 n^d k^(-3/2). Set k=epsilon n^(d-1), yielding exponent (3-d)/2<0. The boundary component already has the L1 surface limit; all other components are negligible on that scale.",["All assumptions of wired-boundary-surface-limit-from-summable-arm-tails","d>3","Full-space cluster-size tail <=K_2 k^(-1/2)"],"C0072_PROOF.md",kind="theorem")
add("C0108","rank-one-quadratic-littlewood-offord-two-preimages","Sharp-order anti-concentration for rank-one squares","For independent uniform signs epsilon_i and nonzero real a_i, Q=(sum a_i epsilon_i)^2 satisfies sup_z P(Q=z)<=2 binom(n,floor(n/2))/2^n; at z=0 the factor 2 is omitted. If all a_i=1 and n is even, P(Q=0)=binom(n,n/2)/2^n, so order n^(-1/2) is attained.","Absorb signs of a_i into the random signs. Each level family of subsets for positive coefficients is an antichain. A uniform permutation chain meets an antichain at most once, yielding sum 1/binom(n,|S|)<=1 and the central-binomial cardinality bound. A positive square level has two linear preimages, zero has one, and negative levels none. The equal-coefficient zero count is the central binomial coefficient; Stirling gives its order.",["Independent uniform {-1,1} signs","All linear coefficients nonzero","Rank-one square form"],"SMALL_CASES_PROOFS.md")
add("C0108","raw-nonzero-quadratic-matrix-entries-can-cancel","All raw matrix entries nonzero does not prevent cancellation","For uniform signs, set c_ii=1, c_ij=1 for i<j, and c_ij=-1 for i>j. Every matrix entry is nonzero, yet Q=sum_(i,j)c_ij epsilon_i epsilon_j=n deterministically. A quadratic anti-concentration hypothesis must control effective off-diagonal coefficients c_ij+c_ji or explicitly assume the intended symmetric nondegenerate matrix.","Pair the (i,j) and (j,i) terms: they cancel for i!=j. Each diagonal term is epsilon_i^2=1, so the sum is n. This checks the literal nonsymmetric raw-entry condition and does not refute the intended symmetric survey conjecture; it is also not the same example for 0/1 variables.",["Uniform {-1,1} signs","Specified nonsymmetric matrix"],"SMALL_CASES_PROOFS.md",role="semantic_association")
add("C0155","independent-poisson-processes-no-monotone-coarse-lipschitz-bijection","No monotone coarse Lipschitz bijection of independent Poisson sets","Two independent homogeneous Poisson processes on R almost surely admit no increasing or decreasing bijection with a finite coarse Lipschitz upper bound |f(x)-f(x')|<=A|x-x'|+B, even when A,B depend on the realization. This does not exclude all quasi-isometries, which need not be bijections.","Every increasing bijection is an index shift k. Far out on the positive tails, corresponding gaps are independent pairs of exponential variables. For fixed k and positive integers A,B, the event X_i<=1 and Y_(i+k)>A+B has a fixed positive probability, independently over i. Independent Borel-Cantelli yields infinitely many violations. A countable union handles all shifts and finite constants. Reflect the target to treat decreasing bijections. No inference about nonbijective monotone maps follows.",["Independent homogeneous Poisson processes of positive intensities","Induced Euclidean metric","Bijection and monotonicity are essential to this obstruction"],"SMALL_CASES_PROOFS.md",role="semantic_association")
add("P0026","fleming-viot-rebirth-quadratic-spread-jump-identity","Conditional spread change at a Fleming-Viot rebirth","For S=sum_(i<j)|x_i-x_j|^2, translate the dead position to zero and let y_1,...,y_(N-1) be surviving displacements. Uniform cloning gives E(Delta S | survivors)=sum_j|y_j|^2-[2/(N-1)]|sum_j y_j|^2.","Use S=N sum_i|x_i|^2-|sum_i x_i|^2. Cloning survivor j changes S by (N-1)|y_j|^2-2 y_j dot sum_i y_i. Averaging over j gives the identity.",["N>=2","Uniform cloning from N-1 survivors","Euclidean positions"],"SMALL_CASES_PROOFS.md",role="semantic_association")
add("P0026","four-particle-rebirth-can-increase-quadratic-spread","Four-particle rebirth can increase spread even in an interval","For N=4 on (0,1), at a death at 0 with survivors 3/4,1/100,1/100, the conditional mean change in pairwise quadratic spread is 5023/30000>0. Uniform mean contraction at every rebirth is therefore false, although this is not an explosion example.","Substitute the three displacements into the jump identity: 9/16+2/10000-(2/3)(77/100)^2=5023/30000. Independently enumerate each of the three equally likely clone choices to obtain the same positive average.",["N=4","Specified one-dimensional endpoint rebirth configuration"],"SMALL_CASES_PROOFS.md",role="semantic_association")
add("P0026","negative-log-boundary-distance-lyapunov-drift-obstruction","Log boundary distance has no uniform linear drift bound","For N independent Brownian particles between rebirths in (0,1), V=-sum_i log dist(x_i,{0,1}) does not satisfy LV<=C(1+V) with any finite uniform C. Already where all x_i<1/2, LV=(1/2)sum_i x_i^(-2), whose ratio to 1+V diverges with one x_i tending to zero and the others fixed at 1/4.","On the indicated smooth region dist(x_i,{0,1})=x_i, so differentiate -log(x_i) twice and use the Brownian generator (1/2)Delta. The diverging term is of order epsilon^(-2), while V grows only as log(1/epsilon). This is an obstruction for this candidate function, not a non-explosion or explosion result; clone jumps require separate analysis.",["Unit interval","Independent standard Brownian motion between rebirths","All coordinates below 1/2 in the drift calculation"],"SMALL_CASES_PROOFS.md",role="semantic_association")

by_key={e['key']:e for e in entries}
